{"filePath": "/app/util/util.go", "oldString": "// Mapify converts a list of objects to a map.", "newString": "// ParseInvocationOptions parses the full command
// arguments of an ABS invocation (argv, including
// the program name at index 0) and returns the
// module-related options that were set on the
// command line.
//
// It understands the following flags:
//
//	--module-path value
//	--module-path=value
//	--module-debug
//
// Everything else is ignored: unknown flags do
// not stop the parsing, so that the script path
// (and arguments following it) can still be
// detected through ParseInvocationOptions' helper
// functions.
func ParseInvocationOptions(argv []string) *InvocationOptions {
	options := &InvocationOptions{}

	for i := 1; i < len(argv); i++ {
		arg := argv[i]

		if options.ScriptPath != "" {
			// everything after the script path
			// is the script's own business
			break
		}

		if arg == "--module-debug" {
			options.ModuleDebug = true
			continue
		}

		if arg == "--module-path" {
			if i+1 < len(argv) {
				options.ModulePath = append(options.ModulePath, argv[i+1])
				i++
			}
			continue
		}

		if strings.HasPrefix(arg, "--module-path=") {
			options.ModulePath = append(options.ModulePath, strings.TrimPrefix(arg, "--module-path="))
			continue
		}

		if !strings.HasPrefix(arg, "-") {
			// this is the script path: whatever
			// comes before was an (unknown) flag
			// and should not stop script detection
			options.ScriptPath = arg
			continue
		}
	}

	return options
}

// FindInvocationScript returns the index of the
// first non-flag argument in argv (skipping the
// program name at index 0), as that is the script
// that was asked to run. It returns -1 if there
// is no script (interactive mode).
//
// Flags that take a value (eg. --module-path
// /some/dir) cannot know whether the value is a
// flag or the script, so callers should parse the
// invocation through ParseInvocationOptions when
// they need accurate script detection.
func FindInvocationScript(argv []string) int {
	for i := 1; i < len(argv); i++ {
		if !strings.HasPrefix(argv[i], "-") {
			return i
		}
	}

	return -1
}

// InvocationOptions holds module-related options
// parsed from the command line invocation
type InvocationOptions struct {
	// ScriptPath is the path of the script
	// that was asked to run, empty in
	// interactive mode
	ScriptPath string
	// ModulePath collects the values of
	// (possibly repeated) --module-path flags
	ModulePath []string
	// ModuleDebug tells whether --module-debug
	// was set
	ModuleDebug bool
}

