// ABS_MODULE_PATH is the name of the OS / runtime
// environment variable holding a list of directories
// (separated by the OS path list separator) where
// modules are looked up, in addition to the base
// directory of the requiring file.
const ABS_MODULE_PATH = "ABS_MODULE_PATH"

// ABS_MODULE_DEBUG is the name of the OS / runtime
// environment variable enabling module loading debug
// traces.
const ABS_MODULE_DEBUG = "ABS_MODULE_DEBUG"

// moduleCache is a map of canonical module paths
// to the module's exported value.
var moduleCache map[string]object.Object

// moduleLoadStack keeps track of the modules that are
// currently being loaded, in load order: this is how
// we detect cyclic imports.
var moduleLoadStack []string

// moduleLoadIndex allows us to tell whether a module
// is already in the load stack without scanning the
// whole stack.
var moduleLoadIndex map[string]bool

// cacheHits and cacheMisses are simple statistics
// about the effectiveness of the module cache.
var cacheHits, cacheMisses int

// moduleAliases keeps package aliases
// (from packages.abs.json) once loaded
var moduleAliases map[string]string
var moduleAliasesLoaded bool

// moduleDebugFromCLI tells whether the --module-debug
// flag was provided on the command line
var moduleDebugFromCLI bool

// modulePathFromCLI collects the values of (possibly
// repeated) --module-path flags provided on the command
// line: these are added to the module lookup paths.
var modulePathFromCLI []string

func init() {
	moduleCache = make(map[string]object.Object)
	moduleLoadIndex = make(map[string]bool)
}

// SetModuleDebugFromCLI records whether the
// --module-debug flag was used in the current
// invocation
func SetModuleDebugFromCLI(moduleDebug bool) {
	moduleDebugFromCLI = moduleDebug
}

// AddModulePathsFromCLI records directories provided
// through --module-path flags in the current
// invocation
func AddModulePathsFromCLI(paths []string) {
	modulePathFromCLI = append(modulePathFromCLI, paths...)
}

// canonicalModulePath returns the canonical, absolute
// representation of the given path, with symlinks
// and relative segments resolved: equivalent paths
// pointing to the same file share the same canonical
// representation and, thus, the same cache entry.
//
// If the path cannot be canonicalized (eg. it does
// not exist yet), a cleaned absolute version of it is
// returned instead: this still makes sure equivalent
// paths (eg. "a/../b.abs" and "b.abs") map to the
// same key.
func canonicalModulePath(path string) string {
	if resolved, err := filepath.EvalSymlinks(path); err == nil {
		if absolute, err := filepath.Abs(resolved); err == nil {
			return absolute
		}
	}

	absolute, err := filepath.Abs(path)
	if err != nil {
		return filepath.Clean(path)
	}

	return filepath.Clean(absolute)
}

// isBareModuleName tells whether the given require
// target is a bare module name: a name without any
// path separator and without file extension (eg.
// "demo"). Bare module names resolve to
// "demo/index.abs".
func isBareModuleName(name string) bool {
	if name == "" || strings.HasPrefix(name, "@") {
		return false
	}

	if strings.ContainsRune(name, os.PathSeparator) || strings.ContainsRune(name, '/') || strings.ContainsRune(name, '\\') {
		return false
	}

	return filepath.Ext(name) == ""
}

// splitModulePathList splits a module path list
// (eg. the content of ABS_MODULE_PATH) into its
// entries: entries are separated by the OS path
// list separator, and may be quoted (eg.
// `"/path/with spaces"`).
func splitModulePathList(list string) []string {
	entries := []string{}

	f := strings.Split(list, string(os.PathListSeparator))

	for _, entry := range f {
		entry = strings.TrimSpace(entry)
		entry = unquoteModulePathEntry(entry)
		entry = strings.TrimSpace(entry)

		if entry != "" {
			entries = append(entries, entry)
		}
	}

	return entries
}

// unquoteModulePathEntry removes symmetric quotes
// around a module path entry: both single and
// double quotes are supported
func unquoteModulePathEntry(entry string) string {
	if len(entry) >= 2 {
		first := entry[0]
		last := entry[len(entry)-1]

		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
			return entry[1 : len(entry)-1]
		}
	}

	return entry
}

// uniqueCanonicalPaths normalizes a list of
// directories to their canonical form, removing
// duplicates while preserving the order in which
// they were first seen
func uniqueCanonicalPaths(paths []string) []string {
	seen := make(map[string]bool)
	list := []string{}

	for _, path := range paths {
		canonical := canonicalModulePath(path)

		if !seen[canonical] {
			seen[canonical] = true
			list = append(list, canonical)
		}
	}

	return list
}

// moduleSearchPaths returns the ordered list of
// directories in which modules are looked up:
// the base directory (the directory of the file
// currently being executed) comes first, then
// the entries of ABS_MODULE_PATH in the order
// they were listed, with CLI-provided paths
// appended as well.
//
// All directories are canonicalized and
// deduplicated, preserving first-seen order.
func moduleSearchPaths(env *object.Environment) []string {
	paths := []string{env.Dir}
	paths = append(paths, modulePathFromCLI...)
	paths = append(paths, splitModulePathList(util.GetEnvVar(env, ABS_MODULE_PATH, ""))...)
	paths = append(paths, splitModulePathList(os.Getenv(ABS_MODULE_PATH))...)

	return uniqueCanonicalPaths(paths)
}

// moduleDebugEnabled tells whether module debug
// traces should be emitted: this is the case when
// the ABS_MODULE_DEBUG variable is truthy in the
// runtime environment (ABS environment first, with
// OS environment fallback) or when the --module-debug
// flag was provided on the command line
func moduleDebugEnabled(env *object.Environment) bool {
	if moduleDebugFromCLI {
		return true
	}

	return isTruthyEnvVar(util.GetEnvVar(env, ABS_MODULE_DEBUG, ""))
}

// isTruthyEnvVar tells whether the value of an
// environment variable is to be considered truthy:
// an empty value, "0", "false" and "no" are falsy,
// anything else is truthy
func isTruthyEnvVar(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", "0", "false", "no":
		return false
	}

	return true
}

// moduleTrace writes a module debug trace to the
// runtime's stderr (the environment's stderr
// stream, not the process' one)
func moduleTrace(env *object.Environment, format string, a ...interface{}) {
	if !moduleDebugEnabled(env) {
		return
	}

	fmt.Fprintf(env.Stdio.Stderr, "[abs:module] "+format+"\n", a...)
}

// resolveModulePath resolves a require target to
// the canonical path of the module to load, or an
// error if no candidate could be found.
//
// Resolution works as follows:
//
//   - "@..." targets are stdlib modules and are
//     returned as-is
//   - aliases (packages.abs.json) are expanded
//   - a target with no path separator and no file
//     extension is a bare module name, resolving
//     to "<name>/index.abs"
//   - a relative or absolute path resolves against
//     the base directory of the requiring file
//   - a bare module name that cannot be found in
//     the base directory is looked up in the
//     directories of ABS_MODULE_PATH, in order
//
// The returned path is canonical, so that
// equivalent paths pointing to the same file share
// a single cache entry.
func resolveModulePath(env *object.Environment, name string) (string, bool) {
	name = util.UnaliasPath(name, moduleAliases)

	// stdlib modules (eg. require('@runtime')) are
	// addressed by name, not by path
	if strings.HasPrefix(name, "@") {
		return name, true
	}

	expanded, err := util.ExpandPath(name)
	if err == nil {
		name = expanded
	}

	// bare module names (eg. "demo") resolve
	// to "demo/index.abs"
	target := name
	if isBareModuleName(name) {
		target = filepath.Join(name, "index.abs")
	}

	// A path is "anchored" when it is absolute or
	// explicitly relative (eg. "./demo" or
	// "../demo"): anchored paths only resolve
	// against the base directory.
	anchored := filepath.IsAbs(target) ||
		strings.HasPrefix(target, "./") ||
		strings.HasPrefix(target, "../") ||
		strings.HasPrefix(target, "~")

	for _, dir := range moduleSearchPaths(env) {
		candidate := target

		if !filepath.IsAbs(candidate) {
			candidate = filepath.Join(dir, candidate)
		}

		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			return canonicalModulePath(candidate), true
		}

		// anchored paths are not searched any
		// further than the base directory
		if anchored {
			break
		}
	}

	// The module might not exist (yet): we still
	// return a canonical path so the error message
	// and the (missing) cache key are deterministic.
	if anchored || !isBareModuleName(name) {
		candidate := target

		if !filepath.IsAbs(candidate) {
			candidate = filepath.Join(env.Dir, candidate)
		}

		return canonicalModulePath(candidate), false
	}

	// an unresolvable bare module name is reported
	// relative to the base directory
	return canonicalModulePath(filepath.Join(env.Dir, target)), false
}

// requireModule loads (or returns the cached value
// of) the module with the given name.
//
// Modules are cached by canonical path, so
// equivalent paths pointing to the same file are
// only ever loaded once. Cyclic imports (eg. a
// module requiring itself, directly or indirectly)
// fail with an error.
func requireModule(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	if err := validateArgs(tok, "require", args, 1, [][]string{{object.STRING_OBJ}}); err != nil {
		return err
	}

	if !moduleAliasesLoaded {
		a, err := os.ReadFile("./packages.abs.json")

		// We couldn't open the packages, file, possibly doesn't exists
		// and the code shouldn't fail
		if err == nil {
			// Try to decode the packages file:
			// if an error occurs we will simply
			// ignore it
			json.Unmarshal(a, &moduleAliases)
		}

		moduleAliasesLoaded = true
	}

	name := args[0].(*object.String).Value
	file, _ := resolveModulePath(env, name)
	moduleTrace(env, "resolve %s -> %s", name, file)

	// stdlib modules (eg. require('@runtime')) are
	// cached by name
	if cached, ok := moduleCache[file]; ok {
		cacheHits++
		moduleTrace(env, "cache hit %s", file)
		return cached
	}

	cacheMisses++

	if moduleLoadIndex[file] {
		// this module is already being loaded: we
		// have a cycle
		cycle := append(append([]string{}, moduleLoadStack...), file)
		moduleTrace(env, "cycle detected %s", strings.Join(cycle, " -> "))
		return newError(tok, "cyclic module import detected: %s", strings.Join(cycle, " -> "))
	}

	moduleTrace(env, "load %s", file)

	// Each module gets its own environment, with
	// the module's directory as base dir so that
	// its own relative imports work, and without
	// access to the requiring environment.
	moduleDir := env.Dir

	if !strings.HasPrefix(file, "@") {
		moduleDir = filepath.Dir(file)
	}

	e := object.NewEnvironment(object.SystemStdio, moduleDir, env.Version, env.Interactive)
	moduleLoadStack = append(moduleLoadStack, file)
	moduleLoadIndex[file] = true
	evaluated := doSource(tok, e, file, args...)
	moduleLoadStack = moduleLoadStack[:len(moduleLoadStack)-1]
	delete(moduleLoadIndex, file)

	// If a module fails to be imported, let's
	// not cache the result
	switch ret := evaluated.(type) {
	case *object.Error:
		return ret
	default:
		moduleCache[file] = evaluated
	}

	return evaluated
}

// requireCacheInfo returns statistics about the
// module cache:
//
//	{
//		"hits": 0,
//		"misses": 0,
//		"size": 0,
//		"inflight": 0
//	}
//
// "inflight" is the number of modules currently
// being loaded (the active load stack).
func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	if err := validateArgs(tok, "require_cache_info", args, 0, [][]string{}); err != nil {
		return err
	}

	pairs := make(map[object.HashKey]object.HashPair)

	setNumberPair := func(key string, value int) {
		k := &object.String{Token: tok, Value: key}
		pairs[k.HashKey()] = object.HashPair{Key: k, Value: &object.Number{Token: tok, Value: float64(value)}}
	}

	setNumberPair("hits", cacheHits)
	setNumberPair("misses", cacheMisses)
	setNumberPair("size", len(moduleCache))
	setNumberPair("inflight", len(moduleLoadStack))

	return &object.Hash{Token: tok, Pairs: pairs}
}

// requireCacheKeys returns the list of modules
// currently cached, as sorted canonical absolute
// paths
func requireCacheKeysFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	if err := validateArgs(tok, "require_cache_keys", args, 0, [][]string{}); err != nil {
		return err
	}

	keys := make([]string, 0, len(moduleCache))

	for k := range moduleCache {
		keys = append(keys, k)
	}

	sort.Strings(keys)

	elements := make([]object.Object, len(keys))
	for i, k := range keys {
		elements[i] = &object.String{Token: tok, Value: k}
	}

	return &object.Array{Token: tok, Elements: elements}
}

// resetRequireCache clears the module cache and
// the loader state (statistics and load stack)
func resetRequireCacheFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	if err := validateArgs(tok, "reset_require_cache", args, 0, [][]string{}); err != nil {
		return err
	}

	moduleCache = make(map[string]object.Object)
	moduleLoadStack = nil
	moduleLoadIndex = make(map[string]bool)
	cacheHits = 0
	cacheMisses = 0

	return NULL
}
