import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/abs-lang/abs/lexer"
	"github.com/abs-lang/abs/object"
	"github.com/abs-lang/abs/parser"
)

// testEvalInDir evaluates code in an environment
// rooted in the given directory (as if a script
// in that directory was running)
func testEvalInDir(input string, dir string) object.Object {
	env := object.NewEnvironment(object.SystemStdio, dir, "test_version", false)
	return testEvalInEnv(input, env)
}

func testEvalInEnv(input string, env *object.Environment) object.Object {
	lex := lexer.New(input)
	p := parser.New(lex)
	program := p.ParseProgram()

	return BeginEval(program, env, lex)
}

// testEvalCapturedStderr evaluates code in an
// environment whose stderr is captured in a buffer
func testEvalCapturedStderr(input string, env *object.Environment) (object.Object, string) {
	previous := env.Stdio
	stderr := bytes.NewBufferString("")
	env.Stdio = &object.Stdio{Stdin: previous.Stdin, Stdout: previous.Stdout, Stderr: stderr}
	defer func() { env.Stdio = previous }()

	result := testEvalInEnv(input, env)

	return result, stderr.String()
}

func writeModule(t *testing.T, path string, code string) {
	t.Helper()

	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatalf("could not create module dir: %s", err)
	}

	if err := os.WriteFile(path, []byte(code), 0644); err != nil {
		t.Fatalf("could not write module: %s", err)
	}
}

// equivalent paths pointing to the same file should
// reuse a single cache entry, and bare module names
// should resolve to name/index.abs
func TestRequireCanonicalCaching(t *testing.T) {
	defer resetForTests()

	dir := t.TempDir()
	writeModule(t, filepath.Join(dir, "demo", "index.abs"), `return {"a": 1}`)

	// require the same module through equivalent,
	// differently-spelled paths
	code := `
		x = require("demo/index.abs")
		y = require("./demo/index.abs")
		z = require("demo/../demo/index.abs")
		w = require("demo")
		[x.a, y.a, z.a, w.a]
	`
	result := testEvalInDir(code, dir)

	arr, ok := result.(*object.Array)
	if !ok {
		t.Fatalf("expected array, got %T (%s)", result, result.Inspect())
	}

	for _, el := range arr.Elements {
		if el.Inspect() != "1" {
			t.Fatalf("expected all requires to return the cached module, got %s", arr.Inspect())
		}
	}

	info := testEvalInDir(`require_cache_info()`, dir).(*object.Hash)
	// 1 miss (all other requires hit the cache)
	if pair, _ := info.GetPair("misses"); pair.Value.Inspect() != "1" {
		t.Errorf("expected 1 cache miss, got %s", info.Inspect())
	}

	// a single cache entry
	keys := testEvalInDir(`require_cache_keys()`, dir).(*object.Array)
	if len(keys.Elements) != 1 {
		t.Errorf("expected a single cache entry, got %s", keys.Inspect())
	}

	expected := filepath.Join(filepath.Clean(dir), "demo", "index.abs")
	if keys.Elements[0].Inspect() != expected {
		t.Errorf("expected cache key %s, got %s", expected, keys.Elements[0].Inspect())
	}
}

// a bare module name resolves as demo/index.abs, both
// in the base directory and in ABS_MODULE_PATH
// entries (base directory first)
func TestRequireModulePathLookupOrder(t *testing.T) {
	defer resetForTests()

	base := t.TempDir()
	first := t.TempDir()
	second := t.TempDir()

	// "demo" is only found in the second module path
	writeModule(t, filepath.Join(second, "demo", "index.abs"), `return "second"`)
	writeModule(t, filepath.Join(first, "shared", "index.abs"), `return "first"`)

	code := `[require("demo"), require("shared")]`
	paths := strings.Join([]string{first, second}, string(os.PathListSeparator))
	previous := os.Getenv("ABS_MODULE_PATH")
	os.Setenv("ABS_MODULE_PATH", paths)
	defer os.Setenv("ABS_MODULE_PATH", previous)

	result := testEvalInDir(code, base)
	arr, ok := result.(*object.Array)
	if !ok {
		t.Fatalf("expected array, got %s", result.Inspect())
	}

	// "demo" comes from the second entry, "shared"
	// from the first one
	if arr.Elements[0].Inspect() != "second" {
		t.Errorf("expected demo to resolve from the second module path, got %s", arr.Inspect())
	}

	if arr.Elements[1].Inspect() != "first" {
		t.Errorf("expected shared to resolve from the first module path, got %s", arr.Inspect())
	}

	// base directory takes precedence over module paths
	writeModule(t, filepath.Join(base, "demo", "index.abs"), `return "base"`)
	resetForTests()
	result = testEvalInDir(`require("demo")`, base)
	if result.Inspect() != "base" {
		t.Errorf("expected base directory to take precedence, got %s", result.Inspect())
	}
}

// ABS_MODULE_PATH may contain quoted entries, which
// are normalized and deduplicated (first-seen order)
func TestRequireModulePathQuotedAndDeduplicated(t *testing.T) {
	defer resetForTests()

	base := t.TempDir()
	dir := t.TempDir()
	writeModule(t, filepath.Join(dir, "demo", "index.abs"), `return "module-path"`)

	unquoted := dir
	quoted := fmt.Sprintf(`"%s"`, dir)
	relative := filepath.Join(dir, "..", filepath.Base(dir))
	list := strings.Join([]string{quoted, unquoted, relative}, string(os.PathListSeparator))

	previous := os.Getenv("ABS_MODULE_PATH")
	os.Setenv("ABS_MODULE_PATH", list)
	defer os.Setenv("ABS_MODULE_PATH", previous)

	env := object.NewEnvironment(object.SystemStdio, base, "test_version", false)
	result, _ := testEvalCapturedStderr(`require("demo")`, env)

	if result.Inspect() != "module-path" {
		t.Fatalf("expected quoted module path entry to resolve, got %s", result.Inspect())
	}

	paths := moduleSearchPaths(env)
	// base + a single (deduplicated) entry
	if len(paths) != 2 {
		t.Fatalf("expected module search paths to be deduplicated, got %v", paths)
	}

	if paths[1] != filepath.Clean(dir) {
		t.Errorf("expected %s as second search path, got %s", filepath.Clean(dir), paths[1])
	}
}

// require_cache_info / require_cache_keys /
// reset_require_cache expose (and reset) the cache
// state
func TestRequireCacheBuiltins(t *testing.T) {
	defer resetForTests()

	dir := t.TempDir()
	writeModule(t, filepath.Join(dir, "demo", "index.abs"), `return 1`)

	code := `
		require("demo")
		require("demo")
		require_cache_info()
	`
	info, ok := testEvalInDir(code, dir).(*object.Hash)
	if !ok {
		t.Fatalf("expected hash, got %T", info)
	}

	for _, field := range []string{"hits", "misses", "size", "inflight"} {
		if pair, ok := info.GetPair(field); !ok || pair.Value.Type() != object.NUMBER_OBJ {
			t.Fatalf("expected numeric field %s, got %s", field, info.Inspect())
		}
	}

	if pair, _ := info.GetPair("hits"); pair.Value.Inspect() != "1" {
		t.Errorf("expected 1 hit, got %s", info.Inspect())
	}

	if pair, _ := info.GetPair("misses"); pair.Value.Inspect() != "1" {
		t.Errorf("expected 1 miss, got %s", info.Inspect())
	}

	if pair, _ := info.GetPair("size"); pair.Value.Inspect() != "1" {
		t.Errorf("expected size 1, got %s", info.Inspect())
	}

	if pair, _ := info.GetPair("inflight"); pair.Value.Inspect() != "0" {
		t.Errorf("expected 0 inflight modules, got %s", info.Inspect())
	}

	// keys are sorted canonical absolute paths
	keys := testEvalInDir(`require_cache_keys()`, dir).(*object.Array)
	expected := filepath.Join(filepath.Clean(dir), "demo", "index.abs")
	if len(keys.Elements) != 1 || keys.Elements[0].Inspect() != expected {
		t.Errorf("expected cache keys to be [%s], got %s", expected, keys.Inspect())
	}

	// resetting the cache clears entries and stats
	testEvalInDir(`reset_require_cache()`, dir)
	keys = testEvalInDir(`require_cache_keys()`, dir).(*object.Array)
	if len(keys.Elements) != 0 {
		t.Errorf("expected empty cache after reset, got %s", keys.Inspect())
	}

