// cyclic imports fail with an error whose message
// includes the cycle chain, in load order
func TestRequireCyclicImport(t *testing.T) {
	defer resetForTests()

	dir := t.TempDir()
	writeModule(t, filepath.Join(dir, "a.abs"), `return require("b.abs")`)
	writeModule(t, filepath.Join(dir, "b.abs"), `return require("a.abs")`)

	result := testEvalInDir(`require("a.abs")`, dir)
	err, ok := result.(*object.Error)
	if !ok {
		t.Fatalf("expected error for cyclic import, got %s", result.Inspect())
	}

	if !strings.HasPrefix(err.Message, "cyclic module import detected:") {
		t.Fatalf("unexpected error message: %s", err.Message)
	}

	// the chain includes all modules in load order
	chain := fmt.Sprintf("%s -> %s -> %s",
		filepath.Join(filepath.Clean(dir), "a.abs"),
		filepath.Join(filepath.Clean(dir), "b.abs"),
		filepath.Join(filepath.Clean(dir), "a.abs"),
	)

	if !strings.Contains(err.Message, chain) {
		t.Errorf("expected message to contain %q, got %s", chain, err.Message)
	}
}

// debug traces are emitted on the environment's
// stderr when ABS_MODULE_DEBUG is truthy, and
// include resolve, load and cache hit events
func TestRequireDebugTracing(t *testing.T) {
	defer resetForTests()

	dir := t.TempDir()
	writeModule(t, filepath.Join(dir, "demo", "index.abs"), `return 1`)

	env := object.NewEnvironment(object.SystemStdio, dir, "test_version", false)
	env.Set("ABS_MODULE_DEBUG", &object.String{Value: "1"})

	_, stderr := testEvalCapturedStderr(`require("demo"); require("demo")`, env)

	for _, expected := range []string{"resolve", "load", "cache hit"} {
		if !strings.Contains(stderr, expected) {
			t.Errorf("expected trace to contain %q, got %s", expected, stderr)
		}
	}

	// traces go to the environment's stderr, and
	// are disabled without the debug flag
	env = object.NewEnvironment(object.SystemStdio, dir, "test_version", false)
	_, stderr = testEvalCapturedStderr(`require("demo")`, env)
	if stderr != "" {
		t.Errorf("expected no trace without debug enabled, got %s", stderr)
	}

	// OS environment fallback
	previous := os.Getenv("ABS_MODULE_DEBUG")
	os.Setenv("ABS_MODULE_DEBUG", "1")
	defer os.Setenv("ABS_MODULE_DEBUG", previous)

	env = object.NewEnvironment(object.SystemStdio, dir, "test_version", false)
	_, stderr = testEvalCapturedStderr(`require("demo")`, env)
	if stderr == "" {
		t.Errorf("expected trace with ABS_MODULE_DEBUG set in the OS environment")
	}
}

