func evalStringIndexExpression(tok token.Token, str, index object.Object, end object.Object, step object.Object, isRange bool) object.Object {
	stringObject := str.(*object.String)
	runes := []rune(stringObject.Value)
	length := len(runes)

	if isRange {
		if !isValidStart(index) {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), str.Type())
		}
		indexes, err := sliceIndexes(tok, length, index, end, step)
		if err != nil {
			return err
		}
		res := make([]rune, 0, len(indexes))
		for _, i := range indexes {
			res = append(res, runes[i])
		}
		return &object.String{Token: tok, Value: string(res)}
	}

	idxNum, ok := index.(*object.Number)
	if !ok {
		// can't happen due to dispatch, but keep safe
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), str.Type())
	}
	idx := idxNum.Int()
	if idx < 0 { idx = length + idx }
	if idx < 0 || idx >= length { return &object.String{Token: tok, Value: ""} }
	return &object.String{Token: tok, Value: string(runes[idx])}
}
