//
// A positive step iterates forward from the start of the range,
// while a negative step iterates backwards from its end. When
// start or end are omitted (or null), they default to the
// boundaries of the collection based on the direction of the
// step. Negative start and end count from the end of the
// collection (eg. -1 is the last element).
func sliceIndexes(tok token.Token, objType object.ObjectType, length int, start, end, step object.Object) ([]int, object.Object) {
	stepIdx := 1

	// the step, when specified, has to be a number
	// different than 0
	if step != NULL {
		stepObj, ok := step.(*object.Number)

		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}

		stepIdx = stepObj.Int()

		if stepIdx == 0 {
			return nil, newError(tok, "slice step cannot be 0")
		}
	}

	// resolve the start of the range
	var startIdx int

	if startObj, ok := start.(*object.Number); ok {
		startIdx = startObj.Int()

		if startIdx < 0 {
			startIdx += length
		}
	} else if start == NULL {
		if stepIdx > 0 {
			startIdx = 0
		} else {
			startIdx = length - 1
		}
	} else {
		return nil, newError(tok, "index operator not supported: %s on %s", start.Inspect(), objType)
	}

	// resolve the end of the range
	var endIdx int

	if endObj, ok := end.(*object.Number); ok {
		endIdx = endObj.Int()

		if endIdx < 0 {
			endIdx += length
		}
	} else if end == NULL {
		if stepIdx > 0 {
			endIdx = length
		} else {
			endIdx = -1
		}
	} else {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	indexes := []int{}

	if stepIdx > 0 {
		// forward iteration
		if startIdx < 0 {
			startIdx = 0
		}

		if startIdx > length {
			startIdx = length
		}

		if endIdx < 0 {
			endIdx = 0
		}

		if endIdx > length {
			endIdx = length
		}

		for i := startIdx; i < endIdx; i += stepIdx {
			indexes = append(indexes, i)
		}
	} else {
		// backward iteration
		if startIdx < -1 {
			startIdx = -1
		}

		if startIdx > length-1 {
			startIdx = length - 1
		}

		if endIdx < -1 {
			endIdx = -1
		}

		if endIdx > length-1 {
			endIdx = length - 1
		}

		for i := startIdx; i > endIdx; i += stepIdx {
			indexes = append(indexes, i)
		}
	}

