// legacyRangeIndexes returns the list of indexes selected by a
// range without a step (start:end), preserving the semantics of
// non-stepped ranges.
func legacyRangeIndexes(tok token.Token, objType object.ObjectType, length int, start, end object.Object) ([]int, object.Object) {
	startIdx := 0

	if startObj, ok := start.(*object.Number); ok {
		startIdx = startObj.Int()
	} else if start != NULL {
		return nil, newError(tok, "index operator not supported: %s on %s", start.Inspect(), objType)
	}

	// A range's minimum value is 0
	if startIdx < 0 {
		startIdx = 0
	}

	max := length

	// check if the range end is a number
	if endObj, ok := end.(*object.Number); ok {
		// if it's lower than zero, then the end is len(x) - end,
		// else it's the end value itself
		if endObj.Int() < 0 {
			max = int(math.Max(float64(max+endObj.Int()), 0))
		} else if endObj.Int() < max {
			max = endObj.Int()
		}
	} else if end != NULL {
		// if the end index is not a number nor null, then we have an error
		// (null would mean no end, so it's valid)
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	indexes := []int{}

	// if the start is higher than the end, the range
	// selects no indexes
	for i := startIdx; i < max; i++ {
		indexes = append(indexes, i)
	}

	return indexes, nil
}

// rangeIndexes returns the list of indexes selected by a range
// (start:end or start:end:step) over a collection of the
// given length.
func rangeIndexes(tok token.Token, objType object.ObjectType, length int, start, end, step object.Object) ([]int, object.Object) {
	if step != NULL {
		return sliceIndexes(tok, objType, length, start, end, step)
	}

	return legacyRangeIndexes(tok, objType, length, start, end)
}

func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	// when a range specifies a step, its start can be
	// omitted (eg. array[::2])
	isNullableIndex := node.IsRange && node.Step != nil

	switch {
	case left.Type() == object.ARRAY_OBJ && (index.Type() == object.NUMBER_OBJ || (isNullableIndex && index == NULL)):
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && (index.Type() == object.NUMBER_OBJ || (isNullableIndex && index == NULL)):
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

