func (p *Parser) parseIndexExpression(left ast.Expression) ast.Expression {
	exp := &ast.IndexExpression{Token: p.curToken, Left: left}

	if p.peekTokenIs(token.COLON) {
		// the start of a range can be omitted (eg. some[:10]);
		// when the range has no step, it defaults to 0,
		// else it is left empty so that the evaluator can
		// pick the right default based on the step's sign
		exp.Index = nil
		exp.IsRange = true
	} else {
