}

func (l ActionPinningLevelString) toLevel() (ActionPinningLevel, error) {
	switch string(l) {
	case "major-minor":
		return ActionPinningLevelMajorMinor, nil
	case "semver":
		return ActionPinningLevelSemver, nil
	case "commit-sha":
		return ActionPinningLevelCommitSHA, nil
	default:
