{"content": "package actionlint

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// Pinning level is ordered by its strictness. A ref satisfying some stricter level also satisfies
// some weaker level.
// https://github.com/rhysd/actionlint/blob/main/docs/config.md

var (
	reActionPinningMajorMinor = regexp.MustCompile(`^v\d+\.\d+$`)
	reActionPinningSemver     = regexp.MustCompile(`^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$`)
	reActionPinningCommitSHA  = regexp.MustCompile(`^[0-9a-f]{40}$`)
)

func reActionPinningLevel(l ActionPinningLevel) (*regexp.Regexp, *regexp.Regexp) {
	switch l {
	case ActionPinningLevelMajorMinor:
		return reActionPinningMajorMinor, reActionPinningSemver
	case ActionPinningLevelSemver:
		return reActionPinningSemver, reActionPinningSemver
	case ActionPinningLevelCommitSHA:
		return reActionPinningCommitSHA, reActionPinningCommitSHA
	default:
		panic("invalid pinning level")
	}
}

func (rule *RuleActionPinning) actionPinningAllowed(allowed bool, owner, repo string) bool {
	o, r := strings.ToLower(owner), strings.ToLower(repo)
	for _, a := range rule.allowedOwners {
		if o == strings.ToLower(a) {
			allowed = true
			break
		}
	}
	for _, a := range rule.allowedActions {
		if o == strings.ToLower(strings.SplitN(a, "/", 2)[0]) && r == strings.ToLower(strings.SplitN(a, "/", 2)[1]) {
			allowed = true
			break
		}
	}
	for _, d := range rule.deniedOwners {
		if o == strings.ToLower(d) {
			return false
		}
	}
	for _, d := range rule.deniedActions {
		if o == strings.ToLower(strings.SplitN(d, "/", 2)[0]) && r == strings.ToLower(strings.SplitN(d, "/", 2)[1]) {
			return false
		}
	}
	return allowed
}

func describePinnedRefs(l ActionPinningLevel) string {
	switch l {
	case ActionPinningLevelMajorMinor:
		return "a major and minor version like \"v4.2\""
	case ActionPinningLevelCommitSHA:
		return "a full 40 characters commit SHA like \"11bd71901bbe5b1630ceea73d27597364ee9f3f4\""
	default:
		return "a semantic version like \"v4.2.1\""
	}
}

// RuleActionPinning is a rule to check that actions and reusable workflows at "uses:" are pinned
// to immutable versions. This rule is disabled by default. It is enabled by the "action-pinning"
// configuration in "actionlint.yaml" or by the "-action-pinning-level" command line option.
// https://docs.github.com/en/actions/security-for-github-actions/security-guides/security-hardening-for-github-actions#using-third-party-actions
type RuleActionPinning struct {
	RuleBase
	workflowPath  string
	levelOverride *ActionPinningLevel
	levelCLI      ActionPinningLevel
	level         ActionPinningLevel
	allowedOwners []string
	allowedActions []string
	deniedOwners []string
	deniedActions []string
}

// NewRuleActionPinning creates a new RuleActionPinning instance. The workflowPath is a file path
// to the workflow which is relative to a project root directory or an absolute path.
func NewRuleActionPinning(workflowPath string) *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: RuleBase{
			name: "action-pinning",
			desc: "Checks that actions and reusable workflows at \"uses:\" are pinned to immutable versions",
		},
		workflowPath: workflowPath,
	}
}

func (rule *RuleActionPinning) SetLevel(l ActionPinningLevel) {
	rule.levelCLI = l
}

func (rule *RuleActionPinning) init() {
	if rule.levelCLI != 0 {
		// The `-action-pinning-level` command line option has the highest precedence.
		rule.level = rule.levelCLI
	} else {
		var cfg *ActionPinningConfig
		if rule.config != nil {
			cfg = rule.config.ActionPinning
			for _, c := range rule.config.PathConfigs(rule.workflowPath) {
				if c.ActionPinning != nil {
					l, err := c.ActionPinning.toLevel()
					if err != nil {
						panic(err) // Already validated when parsing the config
					}
					rule.levelOverride = &l
				}
			}
		}
		switch {
		case rule.levelOverride != nil:
			rule.level = *rule.levelOverride
		case cfg != nil:
			rule.level = cfg.Level
		default:
			rule.level = 0
		}
		if cfg != nil {
			rule.allowedOwners = cfg.AllowedOwners
			rule.allowedActions = cfg.AllowedActions
			rule.deniedOwners = cfg.DeniedOwners
			rule.deniedActions = cfg.DeniedActions
		}
	}
}

func (rule *RuleActionPinning) enabled() bool {
	return rule.level != 0
}

// VisitWorkflowPre is callback when visiting Workflow node before visiting its children.
func (rule *RuleActionPinning) VisitWorkflowPre(n *Workflow) error {
	rule.init()
	if !rule.enabled() {
		return nil
	}
	rule.Debug("Checking version pinning at \"uses:\" with level %q", rule.level)
	return nil
}

// VisitJobPre is callback when visiting Job node before visiting its children.
func (rule *RuleActionPinning) VisitJobPre(n *Job) error {
	if !rule.enabled() {
		return nil
	}
	if n.WorkflowCall == nil || n.WorkflowCall.Uses == nil || n.WorkflowCall.Uses.Value == "" {
		return nil
	}
	u := n.WorkflowCall.Uses
	rule.checkUses(u, "reusable workflow")
	return nil
}

// VisitStep is callback when visiting Step node.
func (rule *RuleActionPinning) VisitStep(n *Step) error {
	if !rule.enabled() {
		return nil
	}
	e, ok := n.Exec.(*ExecAction)
	if !ok || e.Uses == nil || e.Uses.Value == "" {
		return nil
	}
	rule.checkUses(e.Uses, "action")
	return nil
}

func (rule *RuleActionPinning) checkUses(uses *String, what string) {
	spec := uses.Value

	if strings.HasPrefix(spec, "./") {
		// Local actions and local reusable workflows are always immutable
		rule.Debug("Skip checking pinning for local %s %q", what, spec)
		return
	}
	if strings.HasPrefix(spec, "docker://") {
		rule.Debug("Skip checking pinning for Docker image %q", spec)
		return
	}

	name, ref, ok := strings.Cut(spec, "@")
	if !ok {
		// Invalid format. This error is reported by the "action" rule and the "workflow-call" rule
		rule.Debug("Skip checking pinning for %q since it does not follow the {owner}/{repo}@{ref} format", spec)
		return
	}

	if ContainsExpression(name) {
		// The action name is dynamically composed. Nothing can be checked
		rule.Debug("Skip checking pinning for %q since its name is a dynamic expression", spec)
		return
	}

	owner, rest, ok := strings.Cut(name, "/")
	if !ok {
		// Invalid format. This error is reported by the "action" rule and the "workflow-call" rule
		rule.Debug("Skip checking pinning for %q since it does not follow the {owner}/{repo}@{ref} format", spec)
		return
	}
	repo, _, _ := strings.Cut(rest, "/")

	if !rule.actionPinningAllowed(false, owner, repo) {
		rule.Debug("Skip checking pinning for %q since it is allowed by the \"action-pinning\" configuration", spec)
		return
	}

	if ContainsExpression(ref) {
		rule.Errorf(
			uses.Pos,
			"the ref of %s %q is a dynamic expression so actionlint cannot verify that it is pinned to %s. avoid using an expression in the ref at \"uses:\"",
			what,
			spec,
			describePinnedRefs(rule.level),
		)
		return
	}

	if re, reMajor := reActionPinningLevel(rule.level); re.MatchString(ref) || (rule.level == ActionPinningLevelCommitSHA && reMajor != re) {
		rule.Debug("Ref %q of %s %q is pinned with %q level", ref, what, spec, rule.level)
		return
	}

	var knownNote string
	if m, ok := rule.knownVersion(owner, repo); ok {
		knownNote = fmt.Sprintf(" instead. for example, %q is a known version of this %s", m, what)
	}

	rule.Errorf(
		uses.Pos,
		"the ref of %s %q is not pinned to %s. see the document for more details: https://github.com/rhysd/actionlint/blob/main/docs/checks.md#check-action-pinning%s",
		what,
		spec,
		describePinnedRefs(rule.level),
		knownNote,
	)
}

func (rule *RuleActionPinning) knownVersion(owner, repo string) (string, bool) {
	name := owner + "/" + repo
	versions := map[string]struct{}{}
	for spec := range PopularActions {
		if s, _, ok := strings.Cut(spec, "@"); ok && strings.EqualFold(s, name) {
			if ref, _, ok := strings.Cut(spec, "@"); ok {
				if _, ok := versions[ref]; !ok {
					versions[ref] = struct{}{}
				}
			}
		}
	}
	for spec := range OutdatedPopularActionSpecs {
		if s, _, ok := strings.Cut(spec, "@"); ok && strings.EqualFold(s, name) {
			if ref, _, ok := strings.Cut(spec, "@"); ok {
				if _, ok := versions[ref]; !ok {
					versions[ref] = struct{}{}
				}
			}
		}
	}
	best := ""
	for v := range versions {
		if reActionPinningMajorMinor.MatchString(v) || reActionPinningSemver.MatchString(v) || reActionPinningCommitSHA.MatchString(v) {
			if best == "" || best < v {
				best = v
			}
		}
	}
	return best, best != ""
}

