// stricter level also satisfies some weaker level.
// https://github.com/rhysd/actionlint/blob/main/docs/checks.md#check-action-pinning
var (
	// "v4.2"
	reActionPinningMajorMinor = regexp.MustCompile(`^v\d+\.\d+$`)
	// "v4.2.1", "v4.2.1-beta.1"
	reActionPinningSemver = regexp.MustCompile(`^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$`)
	// "11bd71901bbe5b1630ceea73d27597364ee9f3f4"
	reActionPinningCommitSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)
)

// reActionPinningRefs returns the regular expressions which match to the refs satisfying the given
// pinning level. The first return value matches to the refs at the level and the second one matches
// to the refs at the stricter levels.
func reActionPinningRefs(l ActionPinningLevel) (*regexp.Regexp, *regexp.Regexp) {
	switch l {
	case ActionPinningLevelMajorMinor:
		return reActionPinningMajorMinor, reActionPinningSemver
	case ActionPinningLevelSemver:
		return reActionPinningSemver, reActionPinningCommitSHA
	case ActionPinningLevelCommitSHA:
		return reActionPinningCommitSHA, nil
	default:
		panic("invalid pinning level")
	}
}

func describePinnedRefs(l ActionPinningLevel) string {
	switch l {
	case ActionPinningLevelMajorMinor:
		return "a major and minor version like \"v4.2\""
	case ActionPinningLevelCommitSHA:
		return "a full 40 characters commit SHA like \"11bd71901bbe5b1630ceea73d27597364ee9f3f4\""
	default:
		return "a semantic version like \"v4.2.1\""
	}
}

type actionPinningAllowedActions struct {
	owners map[string]struct{}
	names  map[string]struct{}
}

func newActionPinningAllowedActions(owners, actions []string) actionPinningAllowedActions {
	ret := actionPinningAllowedActions{
		owners: make(map[string]struct{}, len(owners)),
		names:  make(map[string]struct{}, len(actions)),
	}
	for _, o := range owners {
		ret.owners[strings.ToLower(o)] = struct{}{}
	}
	for _, a := range actions {
		ret.names[strings.ToLower(a)] = struct{}{}
	}
	return ret
}

func (as actionPinningAllowedActions) contains(owner, repo string) bool {
	o := strings.ToLower(owner)
	if _, ok := as.owners[o]; ok {
		return true
	}
	_, ok := as.names[o+"/"+strings.ToLower(repo)]
	return ok
}

// RuleActionPinning is a rule to check that actions and reusable workflows at "uses:" are pinned
// to immutable versions. This rule is disabled by default. It is enabled by the "action-pinning"
// configuration in "actionlint.yaml" or by the "-action-pinning-level" command line option.
// https://docs.github.com/en/actions/security-for-github-actions/security-guides/security-hardening-for-github-actions#using-third-party-actions
type RuleActionPinning struct {
	RuleBase
	workflowPath string
	// cliLevel is a level given via the "-action-pinning-level" command line option. Zero value
	// means the option is not given.
	cliLevel ActionPinningLevel
	// level is the level actually used by this rule. Zero value means this rule is disabled.
	level          ActionPinningLevel
	allowed        actionPinningAllowedActions
	denied         actionPinningAllowedActions
	knownSpecNames map[string][]string
}

// NewRuleActionPinning creates a new RuleActionPinning instance. The workflowPath is a file path
// to the workflow which is relative to a project root directory or an absolute path.
func NewRuleActionPinning(workflowPath string) *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: RuleBase{
			name: "action-pinning",
			desc: "Checks that actions and reusable workflows at \"uses:\" are pinned to immutable versions",
		},
		workflowPath: workflowPath,
	}
}

// SetLevel sets the pinning level given via the "-action-pinning-level" command line option.
func (rule *RuleActionPinning) SetLevel(l ActionPinningLevel) {
	rule.cliLevel = l
}

// VisitWorkflowPre is callback when visiting Workflow node before visiting its children.
func (rule *RuleActionPinning) VisitWorkflowPre(n *Workflow) error {
	var cfg *ActionPinningConfig
	if rule.config != nil {
		cfg = rule.config.ActionPinning
	}

	if rule.cliLevel != 0 {
		// The "-action-pinning-level" command line option has the highest precedence. Note that
		// the option only overrides the level. It does not modify the allow/deny lists.
		rule.level = rule.cliLevel
	} else {
		// The per-path configuration in the "paths" section overrides the level in the global
		// "action-pinning" section.
		var pathLevel *ActionPinningLevel
		if rule.config != nil {
			for _, c := range rule.config.PathConfigs(rule.workflowPath) {
				if c.ActionPinning != nil {
					// This configuration is validated when parsing the config file
					l, err := c.ActionPinning.toLevel()
					if err != nil {
						panic(err)
					}
					pathLevel = &l
				}
			}
		}
		switch {
		case pathLevel != nil:
			rule.level = *pathLevel
		case cfg != nil:
			rule.level = cfg.Level
		default:
			rule.level = 0 // Disabled
		}
	}

	if cfg != nil {
		rule.allowed = newActionPinningAllowedActions(cfg.AllowedOwners, cfg.AllowedActions)
		rule.denied = newActionPinningAllowedActions(cfg.DeniedOwners, cfg.DeniedActions)
	}

	if rule.level == 0 {
		rule.Debug("This rule is disabled since neither the \"action-pinning\" configuration nor the \"+-action-pinning-level\" option is set")
	} else {
		rule.Debug("Checking the version pinning at \"uses:\" with %q level", rule.level)
	}
	return nil
}

// VisitJobPre is callback when visiting Job node before visiting its children.
func (rule *RuleActionPinning) VisitJobPre(n *Job) error {
	if rule.level == 0 {
		return nil
	}
	if n.WorkflowCall == nil || n.WorkflowCall.Uses == nil || n.WorkflowCall.Uses.Value == "" {
		return nil
	}
	rule.checkUses(n.WorkflowCall.Uses, "reusable workflow")
	return nil
}

// VisitStep is callback when visiting Step node.
func (rule *RuleActionPinning) VisitStep(n *Step) error {
	if rule.level == 0 {
		return nil
	}
	e, ok := n.Exec.(*ExecAction)
	if !ok || e.Uses == nil || e.Uses.Value == "" {
		return nil
	}
	rule.checkUses(e.Uses, "action")
	return nil
}

func (rule *RuleActionPinning) checkUses(uses *String, what string) {
	spec := uses.Value

	if strings.HasPrefix(spec, "./") {
		// Local actions and local reusable workflows are in the same repository. They are always
		// immutable.
		rule.Debug("Skip checking the pinning for local %s %q", what, spec)
		return
	}
	if strings.HasPrefix(spec, "docker://") {
		rule.Debug("Skip checking the pinning for Docker image %q", spec)
		return
	}

	name, ref, found := strings.Cut(spec, "@")
	if !found {
		// The format is invalid. This error is reported by the "action" rule or the
		// "workflow-call" rule.
		rule.Debug("Skip checking the pinning for %q since it follows neither the {owner}/{repo}@{ref} format nor the {owner}/{repo}/{path}@{ref} format", spec)
		return
	}

	if ContainsExpression(name) {
		// The name of the action is dynamically composed with expressions. Nothing can be checked
		rule.Debug("Skip checking the pinning for %q since its name is dynamically composed with an expression", spec)
		return
	}

	owner, rest, ok := strings.Cut(name, "/")
	if !ok {
		// The format is invalid. This error is reported by the "action" rule or the
		// "workflow-call" rule.
		rule.Debug("Skip checking the pinning for %q since it follows neither the {owner}/{repo}@{ref} format nor the {owner}/{repo}/{path}@{ref} format", spec)
		return
	}
	repo, _, _ := strings.Cut(rest, "/")

	if rule.denied.contains(owner, repo) {
		// The denied lists take precedence over the allowed lists. The action or the reusable
		// workflow is still checked by this rule.
		rule.Debug("Check the pinning for %q since it is denied by the \"denied-owners\" or \"denied-actions\" configuration", spec)
	} else if rule.allowed.contains(owner, repo) {
		rule.Debug("Skip checking the pinning for %q since it is allowed by the \"allowed-owners\" or \"allowed-actions\" configuration", spec)
	} else if rule.cliLevel == 0 && rule.allowed.owners != nil || rule.allowed.names != nil {
		// When the action is not in the allowed lists, it is checked by this rule
	}

	if ContainsExpression(ref) {
		// The ref is dynamically composed with expressions. It cannot be verified that the ref is
		// pinned to some immutable version.
		rule.Errorf(
			uses.Pos,
			"the ref of %s %q is a dynamic expression so actionlint cannot verify that it is pinned to %s. avoid using an expression in the ref at \"uses:\"",
			what,
			spec,
			describePinnedRefs(rule.level),
		)
		return
	}

	if rule.isPinned(ref) {
		rule.Debug("The ref %q of %s %q is pinned to %q level", ref, what, spec, rule.level)
		return
	}

	note := ""
	if v, ok := rule.knownVersion(owner, repo); ok {
		note = fmt.Sprintf(" instead. for example, %q is a known version of this %s", v, what)
	}

	rule.Errorf(
		uses.Pos,
		"the ref of %s %q is not pinned to %s. see the document for more details: https://github.com/rhysd/actionlint/blob/main/docs/checks.md#check-action-pinning%s",
		what,
		spec,
		describePinnedRefs(rule.level),
		note,
	)
}

func (rule *RuleActionPinning) isPinned(ref string) bool {
	atLevel, stricter := reActionPinningRefs(rule.level)
	return atLevel.MatchString(ref) || stricter != nil && stricter.MatchString(ref)
}

// knownVersion returns some known version of the given action in the popular actions data set.
// The returned version satisfies the pinning level checked by this rule when possible.
func (rule *RuleActionPinning) knownVersion(owner, repo string) (string, bool) {
	if rule.knownSpecNames == nil {
		m := make(map[string][]string, len(PopularActions)+len(OutdatedPopularActionSpecs))
		for spec := range PopularActions {
			n, ref, ok := strings.Cut(spec, "@")
			if !ok {
				continue
			}
			m[strings.ToLower(n)] = append(m[strings.ToLower(n)], ref)
		}
		for spec := range OutdatedPopularActionSpecs {
			n, ref, ok := strings.Cut(spec, "@")
			if !ok {
				continue
			}
			m[strings.ToLower(n)] = append(m[strings.ToLower(n)], ref)
		}
		rule.knownSpecNames = m
	}
	name := strings.ToLower(owner + "/" + repo)
	refs, ok := rule.knownSpecNames[name]
	if !ok {
		return "", false
	}
	best := ""
	for _, r := range refs {
		if rule.isPinned(r) && (best == "" || r > best) {
			best = r
		}
	}
	if best != "" {
		return best, true
	}
	// No version satisfies the pinning level. Fall back to the newest known version so that the
	// error message can suggest some known version.
	for _, r := range refs {
		if best == "" || r > best {
			best = r
		}
	}
	if best != "" {
		return best, true
	}
	return "", false
}
