{"content": "package actionlint

import (
	"strings"
	"testing"
)

func testRunRuleActionPinning(t *testing.T, src string, cfg *Config, level ActionPinningLevel) []*Error {
	t.Helper()
	w, errs := Parse([]byte(src))
	if len(errs) > 0 {
		t.Fatal(errs)
	}

	r := NewRuleActionPinning("test.yaml")
	if level != 0 {
		r.SetLevel(level)
	}
	if cfg != nil {
		r.SetConfig(cfg)
	}
	v := NewVisitor()
	v.AddPass(r)
	if err := v.Visit(w); err != nil {
		t.Fatal(err)
	}
	return r.Errs()
}

func testParseActionPinningConfig(t *testing.T, src string) *Config {
	t.Helper()
	c, err := ParseConfig([]byte(src))
	if err != nil {
		t.Fatal(err)
	}
	return c
}

func TestRuleActionPinningDisabledByDefault(t *testing.T) {
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
`
	errs := testRunRuleActionPinning(t, src, nil, 0)
	if len(errs) > 0 {
		t.Fatal("the rule must be disabled when no config is set but got", errs)
	}

	errs = testRunRuleActionPinning(t, src, &Config{}, 0)
	if len(errs) > 0 {
		t.Fatal("the rule must be disabled when the config has no \"action-pinning\" section but got", errs)
	}
}

func TestRuleActionPinningNullConfigDisablesRule(t *testing.T) {
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
`
	cfg := testParseActionPinningConfig(t, "action-pinning:\n")
	errs := testRunRuleActionPinning(t, src, cfg, 0)
	if len(errs) > 0 {
		t.Fatal("null \"action-pinning\" config must disable the rule but got", errs)
	}
}

func TestRuleActionPinningEmptyConfigEnablesRule(t *testing.T) {
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
`
	cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
	errs := testRunRuleActionPinning(t, src, cfg, 0)
	if len(errs) != 1 {
		t.Fatal("empty \"action-pinning\" config must enable the rule with the default level but got", errs)
	}
	if !strings.Contains(errs[0].Message, "is not pinned to a semantic version") {
		t.Error("unexpected error message", errs[0].Message)
	}
	if errs[0].Kind != "action-pinning" {
		t.Errorf("unexpected error kind %q", errs[0].Kind)
	}
}

func TestRuleActionPinningLevels(t *testing.T) {
	tests := []struct {
		level ActionPinningLevel
		ref   string
		ok    bool
	}{
		// major-minor
		{ActionPinningLevelMajorMinor, "v4", false},
		{ActionPinningLevelMajorMinor, "v4.2", true},
		{ActionPinningLevelMajorMinor, "v4.2.1", true},
		{ActionPinningLevelMajorMinor, "v4.2.1-beta.1", true},
		{ActionPinningLevelMajorMinor, "11bd71901bbe5b1630ceea73d27597364ee9f3f4", true},
		{ActionPinningLevelMajorMinor, "main", false},
		{ActionPinningLevelMajorMinor, "11bd71901bbe5b1630ceea73d27597364ee9f3f", true},
		// semver (default)
		{ActionPinningLevelSemver, "v4", false},
		{ActionPinningLevelSemver, "v4.2", false},
		{ActionPinningLevelSemver, "v4.2.1", true},
		{ActionPinningLevelSemver, "v4.2.1-beta.1", true},
		{ActionPinningLevelSemver, "v4.2.1+build.1", true},
		{ActionPinningLevelSemver, "11bd71901bbe5b1630ceea73d27597364ee9f3f4", true},
		{ActionPinningLevelSemver, "main", false},
		{ActionPinningLevelSemver, "release/v4", false},
		// commit-sha
		{ActionPinningLevelCommitSHA, "v4.2.1", false},
		{ActionPinningLevelCommitSHA, "11bd71901bbe5b1630ceea73d27597364ee9f3f4", true},
		{ActionPinningLevelCommitSHA, "11BD71901BBE5B1630CEEA73D27597364EE9F3F4", false}, // Not lowercase
		{ActionPinningLevelCommitSHA, "11bd71901bbe5b1630ceea73d27597364ee9f3f", false},  // 39 characters
		{ActionPinningLevelCommitSHA, "main", false},
	}

	for _, tc := range tests {
		t.Run(tc.level.String()+"/"+tc.ref, func(t *testing.T) {
			src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: some/action@` + tc.ref + `
`
			errs := testRunRuleActionPinning(t, src, nil, tc.level)
			if tc.ok && len(errs) > 0 {
				t.Fatal("ref", tc.ref, "must be pinned at level", tc.level, "but got", errs)
			}
			if !tc.ok {
				if len(errs) != 1 {
					t.Fatal("ref", tc.ref, "must not be pinned at level", tc.level, "but got", errs)
				}
				if !strings.Contains(errs[0].Message, "is not pinned to") {
					t.Error("unexpected error message", errs[0].Message)
				}
			}
		})
	}
}

func TestRuleActionPinningSkippedRefs(t *testing.T) {
	tests := []struct {
		what string
		uses string
	}{
		{"local action", "./path/to/action"},
		{"docker action", "docker://alpine:3.13"},
		{"run step", "run: echo 'hi'"},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: ` + tc.uses + `
`
			cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
			errs := testRunRuleActionPinning(t, src, cfg, 0)
			if len(errs) > 0 {
				t.Fatal("no error must be reported for", tc.uses, "but got", errs)
			}
		})
	}
}

func TestRuleActionPinningExpressionInUses(t *testing.T) {
	tests := []struct {
		what string
		uses string
		want string
	}{
		{
			what: "expression in action name",
			uses: "actions/${{ matrix.action }}@v4.2.1",
			want: "",
		},
		{
			what: "expression in ref",
			uses: "actions/checkout@${{ matrix.ref }}",
			want: "dynamic expression",
		},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: ` + tc.uses + `
`
			cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
			errs := testRunRuleActionPinning(t, src, cfg, 0)
			if tc.want == "" {
				if len(errs) > 0 {
					t.Fatal("no error must be reported but got", errs)
				}
				return
			}
			if len(errs) != 1 {
				t.Fatal("one error must be reported but got", errs)
			}
			if !strings.Contains(errs[0].Message, tc.want) {
				t.Error("unexpected error message", errs[0].Message)
			}
		})
	}
}

func TestRuleActionPinningReusableWorkflow(t *testing.T) {
	src := `
on: push
jobs:
  test:
    uses: some/repo/.github/workflows/test.yml@main
`
	cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
	errs := testRunRuleActionPinning(t, src, cfg, 0)
	if len(errs) != 1 {
		t.Fatal("one error must be reported but got", errs)
	}
	if !strings.Contains(errs[0].Message, "the ref of reusable workflow") {
		t.Error("the error message must distinguish the reusable workflow from step actions", errs[0].Message)
	}
}

func TestRuleActionPinningLocalReusableWorkflowIsSkipped(t *testing.T) {
	src := `
on: push
jobs:
  test:
    uses: ./.github/workflows/test.yml
`
	cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
	errs := testRunRuleActionPinning(t, src, cfg, 0)
	if len(errs) > 0 {
		t.Fatal("local reusable workflow must be skipped but got", errs)
	}
}

func TestRuleActionPinningStepActionErrorMessage(t *testing.T) {
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: some/action@main
`
	cfg := testParseActionPinningConfig(t, "action-pinning: {}\n")
	errs := testRunRuleActionPinning(t, src, cfg, 0)
	if len(errs) != 1 {
