from typing import Any, Optional

import pytest
from tests_helpers.misc import full_match, raises_exc, with_trail

from adaptix import CannotProvide, Chain, DebugTrail, ExtraForbid, ExtraKwargs, ExtraSkip, NameStyle, Retort
from adaptix._internal.morphing.model.crown_definitions import (
    ExtraCollect,
    InpDictCrown,
    InpFieldCrown,
    InputNameLayout,
)
from adaptix.load_error import AggregateLoadError, ExtraFieldsLoadError, NoRequiredFieldsLoadError, TypeLoadError
from adaptix.name_mapping import name_mapping


@dataclass
class Book:
    title: str
    price: int


def make_loader_getter(*providers, debug_trail=DebugTrail.ALL):
    def getter():
        retort = Retort(
            recipe=list(providers),
        ).replace(debug_trail=debug_trail)
        return retort.get_loader(Book)

    return getter


def test_aliases_basic_loading():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": ["name", "book_title"]}),
        ],
    )
    loader = retort.get_loader(Book)

    assert loader({"title": "a", "price": 1}) == Book("a", 1)
    assert loader({"name": "a", "price": 1}) == Book("a", 1)
    assert loader({"book_title": "a", "price": 1}) == Book("a", 1)


def test_aliases_do_not_affect_dumping():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": ["name", "book_title"]}),
        ],
    )
    assert retort.dump(Book("a", 1)) == {"title": "a", "price": 1}


def test_aliases_single_string():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": "name"}),
        ],
    )
    loader = retort.get_loader(Book)
    assert loader({"title": "a", "price": 1}) == Book("a", 1)
    assert loader({"name": "a", "price": 1}) == Book("a", 1)


def test_aliases_optional_field():
    @dataclass
    class Model:
        a: str = "default"

    retort = Retort(
        recipe=[
            name_mapping(Model, aliases={"a": "x"}),
        ],
    )
    loader = retort.get_loader(Model)
    assert loader({}) == Model()
    assert loader({"a": "1"}) == Model("1")
    assert loader({"x": "1"}) == Model("1")


def test_aliases_multiple_keys_conflict():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": ["name", "book_title"]}),
        ],
    )
    loader = retort.get_loader(Book)

    data = {"name": "a", "book_title": "b", "price": 1}
    raises_exc(
        AggregateLoadError(
            f"while loading model {Book}",
            [ExtraFieldsLoadError({"name", "book_title"}, data)],
        ),
        lambda: loader(data),
    )


def test_alias_conflicts_with_primary_key_of_same_field():
    getter = make_loader_getter(
        name_mapping(Book, aliases={"title": "title"}),
    )
    with pytest.raises(CannotProvide) as exc_info:
        getter()
    assert full_match(
        "Cannot produce loader for type <class 'tests.unit.morphing.name_layout.test_aliases"
        f".test_alias_conflicts_with_primary_key_of_same_field.<locals>.Book'>",
    ) not in str(exc_info)


def test_alias_equal_to_own_key_error():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": "title"}),
        ],
    )
    with pytest.raises(Exception, match=".*Alias 'title' of field 'title' is equal to its own key.*"):
        retort.get_loader(Book)


def test_alias_collides_with_other_field_key():
    retort = Retort(
        recipe=[
            name_mapping(Book, aliases={"title": "price"}),
