        snapshot was captured.
        """
        snapshot = self.get_snapshot(snapshot_id)
        tasks = []
        for task in sorted(snapshot.running_tasks, key=id):
            taskid = str(id(task))
            chain = snapshot.running_task_chains.get(taskid) or [None]
            creation_stack = next(
                (stack for stack in chain if stack is not None), None
            )
            if creation_stack is None:
                created_location = "-"
            else:
                fn = _format_filename(creation_stack[-1].filename)
                lineno = creation_stack[-1].lineno
                created_location = f"{fn}:{lineno}"
            started_at = snapshot.running_started_ats.get(id(task))
            if started_at is None:
                running_since = "-"
            else:
                running_since = _format_timedelta(
                    timedelta(seconds=snapshot.perf_counter - started_at)
                )
            tasks.append(
                FormattedLiveTaskInfo(
                    taskid,
                    task._state,
                    task.get_name(),
                    snapshot.running_coro_reprs.get(id(task), "-"),
                    created_location,
                    running_since,
