        self, snapshot_id: int | str
    ) -> Sequence[FormattedTerminatedTaskInfo]:
        """
        Return the frozen list of the tasks that were already terminated when
        the given snapshot was captured.
        """
        snapshot = self.get_snapshot(snapshot_id)
        tasks = []
        for item in sorted(
            snapshot.terminated_tasks,
            key=lambda info: info.terminated_at,
            reverse=True,
        ):
            started_since = _format_timedelta(
                timedelta(seconds=snapshot.perf_counter - item.started_at)
            )
            terminated_since = _format_timedelta(
                timedelta(seconds=snapshot.perf_counter - item.terminated_at)
            )
            tasks.append(
                FormattedTerminatedTaskInfo(
                    str(item.id),
                    item.name,
                    item.coro,
                    started_since,
                    terminated_since,
