    ) -> Sequence[FormattedStackItem]:
        """
        Return the frozen stack frames and the task creation chain of a task
        that was running when the given snapshot was captured.
        """
        snapshot = self.get_snapshot(snapshot_id)
        task_id_ = int(task_id)
        task = next(
            (t for t in snapshot.running_tasks if id(t) == task_id_), None
        )
        if task is None:
            raise MissingTask(task_id_)
        chain = snapshot.running_task_chains.get(str(task_id_), [None])
        task_repr = f"<Task name={task.get_name()} coro={snapshot.running_coro_reprs.get(task_id_, '-')}>"
        formatted_stack_list = []
        for depth in range(len(chain) - 1, -1, -1):
            if depth == len(chain) - 1:
                formatted_stack_list.append(
                    FormattedStackItem(
