    def format_snapshot_diff(
        self,
        snapshot_id_1: int | str,
        snapshot_id_2: int | str,
    ) -> SnapshotDiffInfo:
        """
        Compare the running task states of the two snapshots by the task object
        IDs and return the added, removed, and common task items.
        """
        snapshot_1 = self.get_snapshot(snapshot_id_1)
        snapshot_2 = self.get_snapshot(snapshot_id_2)
        if snapshot_1.id == snapshot_2.id:
            return SnapshotDiffInfo(added=[], removed=[], common=[])
        items_1 = {
            item.task_id: item
            for item in self.format_snapshot_task_list(snapshot_1.id)
        }
        items_2 = {
            item.task_id: item
            for item in self.format_snapshot_task_list(snapshot_2.id)
        }
        added = [items_2[key] for key in sorted(items_2.keys() - items_1.keys(), key=int)]
        removed = [
            items_1[key] for key in sorted(items_1.keys() - items_2.keys(), key=int)
        ]
        common = [
            items_1[key] for key in sorted(items_1.keys() & items_2.keys(), key=int)
        ]
        return SnapshotDiffInfo(added=added, removed=removed, common=common)

